manifestSchema = z
  .object({
    schemaVersion: z.literal(1),
    compilerVersion: z.string().regex(/^\d+\.\d+\.\d+$/),
    entityId: id,
    identityVersion: hash,
    sourceFingerprint: hash,
    compiledAt: z.string().datetime(),
    status: z.enum(["complete", "partial"]),
    entity: z
      .object({
        id,
        name: z.string(),
        category: z.string().nullable(),
        tags: z.array(z.string()),
        createdAt: z.string().nullable(),
      })
      .strict(),
    indexedMenus: z.array(
      z
        .object({
          id: z.string(),
          title: z.string(),
          sourceIds: z.array(sourceId),
        })
        .strict(),
    ),
    sources: z.array(sourceSchema).max(LIMITS.sources),
    // Optional only for immutable snapshots produced before compiler 1.1.0.
    connections: z
      .object({
        inputs: z.array(connectionSchema.extend({ type: z.literal("input") })),
        outputs: z.array(
          connectionSchema.extend({ type: z.literal("output") }),
        ),
        unavailableCount: z.number().int().nonnegative(),
      })
      .strict()
      .optional(),
    knowledge: z
      .object({
        chunkCount: z.number().int().min(0).max(LIMITS.chunks),
        tokenEstimate: z.number().int().nonnegative(),
        chunkIndexHash: hash,
        retrieval: z.literal("entity-scoped-chunks"),
      })
      .strict(),
    capabilities: z
      .array(
        capabilitySchema.pick({
          capabilityId: true,
          engineId: true,
          version: true,
          operation: true,
          availability: true,
          sourceId: true,
          symbol: true,
        }),
      )
      .max(1000),
    capabilityRegistryHash: hash,
    log: logSchema,
  })
  .strict()
  .superRefine((manifest, context) => {
    for (const [kind, connections] of Object.entries(
      manifest.connections ?? {},
    )) {
      if (!Array.isArray(connections)) continue;
      for (const [index, connection] of connections.entries()) {
        const endpoint =
          kind === "inputs"
            ? connection.targetEntityId
            : connection.sourceEntityId;
        if (
          connection.sourceEntityId === connection.targetEntityId ||
          (connection.direction === "directed"
            ? endpoint !== manifest.entityId
            : ![connection.sourceEntityId, connection.targetEntityId].includes(
                manifest.entityId,
              ))
        )
          context.addIssue({
            code: "custom",
            path: ["connections", kind, index],
            message: "Connection does not match the entity's flow.",
          });
      }
    }
  })

snapshotSchema = z
  .object({
    schemaVersion: z.literal(1),
    engineVersion: z.literal(VERSION),
    provider: z.literal("Yahoo Finance"),
    symbol: z.string().regex(/^[A-Z0-9^][A-Z0-9.^=_-]{0,31}$/),
    currency: z.string().min(1).max(12),
    exchangeTimezone: z.string().min(1).max(80),
    price: z.number().finite().nonnegative(),
    previousClose: z.number().finite().nonnegative().nullable(),
    marketTime: z.string().datetime(),
    marketState: z.string().max(40),
    delayMinutes: z.number().finite().nonnegative().nullable(),
    fetchedAt: z.string().datetime(),
    historyFetchedAt: z.string().datetime(),
    metrics: z
      .object({
        marketCap: z.number().finite().nullable(),
        trailingPE: z.number().finite().nullable(),
        eps: z.number().finite().nullable(),
        week52Low: z.number().finite().nullable(),
        week52High: z.number().finite().nullable(),
        volume: z.number().finite().nullable(),
      })
      .strict()
      .optional(),
    history: z
      .array(
        z
          .object({
            date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
            close: z.number().finite().nonnegative(),
          })
          .strict(),
      )
      .min(1)
      .max(400),
  })
  .strict()
  .refine(function validTimezone(value) {
    try {
      new Intl.DateTimeFormat("en-US", { timeZone: value.exchangeTimezone });
      return true;
    } catch (error) {
      if (error instanceof RangeError) return false;
      throw error;
    }
  }, "Exchange timezone is invalid.")
  .refine(function ordered(value) {
    return value.history.every(function increasing(point, index, points) {
      return (
        Number.isFinite(Date.parse(point.date)) &&
        new Date(point.date).toISOString().slice(0, 10) === point.date &&
        (!index || point.date > points[index - 1].date)
      );
    });
  }, "Daily observations must be valid dates in chronological order.")

snapshotSchema = z
  .object({
    schemaVersion: z.literal(1),
    provider: z.literal("Yahoo Finance"),
    symbol: z.string(),
    kind: z.enum(["financials", "earnings"]),
    fetchedAt: z.string().datetime(),
    currency: z.string().nullable(),
    warnings: z.array(z.string()),
    statements: z.record(
      z.string(),
      z
        .object({
          annual: z.array(recordSchema).max(100),
          quarterly: z.array(recordSchema).max(100),
        })
        .strict(),
    ),
    history: z
      .array(
        z
          .object({
            periodEnd: z.string().date().nullable(),
            announcementDate: z.string().datetime().nullable(),
            currency: z.string().nullable(),
            estimate: nullableNumber,
            actual: nullableNumber,
            surprise: nullableNumber,
            surpriseBasis: z.enum(["provider", "computed"]).nullable(),
          })
          .strict(),
      )
      .max(100),
    scheduled: z
      .array(
        z
          .object({
            date: z.string().datetime(),
            estimated: z.boolean().nullable(),
          })
          .strict(),
      )
      .max(20),
  })
  .strict()
  .refine(function completeDataset(snapshot) {
    return (
      snapshot.kind !== "financials" ||
      ["income_statement", "balance_sheet", "cash_flow"].every((name) =>
        Object.hasOwn(snapshot.statements, name),
      )
    );
  }, "Financial cache is incomplete.")

