export type ChatPanelProps = {
  variant?: "panel" | "floating" | "workspace" | "window";
  controller: ChatController;
  onOpenSource: (path: string) => void;
  onExpandContext?: () => void;
  onUndock?: () => void;
  onPopOutWindow?: () => void;
  onAttachWindow?: () => void;
  onOpenAgentSettings?: () => void;
