contract.declaration:
export type ModelMessage = {
  role: "system" | "user" | "assistant";
  content: string;
};

export type ModelRequest = {
  id: string;
  model: string;
  messages: ModelMessage[];
  scope?: BrainScope;
  format?: Record<string, unknown>;
  contextWindow?: number;
  settings?: ModelSettings;
  signal?: AbortSignal;
  onContent?: (content: string) => void;
};

export type ModelRuntimeErrorValue = {
  code: ModelErrorCode | BrainErrorCode;
  message: string;
  details: Record<string, unknown>;
};

export type LocalModel = {
  name: string;
  model: string;
  size: number;
  digest: string;
  modifiedAt: string | null;
  family: string | null;
  parameterSize: string | null;
  quantization: string | null;
  contextLength: number | null;
  outputLimit?: number | null;
  capabilities: string[];
};

export type ModelStatus = {
  provider: "ollama";
  endpoint: string;
  online: boolean;
  checkedAt: string;
  models: LocalModel[];
  error: ModelRuntimeErrorValue | null;
};

export type ModelSourceReference = {
  sourceId: string;
  relativePath: string;
  contentHash: string;
};

export type ModelAvailableSourceReference = {
  sourceId: string;
  relativePath: string;
  contentHash: string | null;
};

export type ModelResponse = {
  id: string;
  provider: string;
  model: string;
  content: string;
  sources: ModelSourceReference[];
  finishReason: string;
  createdAt: string;
  usage: {
    promptTokens: number | null;
    completionTokens: number | null;
    totalDurationNs: number | null;
  };
};

export type ContextModelResult = ModelResponse & {
  scopeId: string;
  scopeMode: "active-context";
  scopeManifestVersion: string;
  promptVersion: string;
};

export type ModelRunErrorValue = {
  code: ModelErrorCode | BrainErrorCode;
  message: string;
  details: Record<string, unknown>;
};

export type ModelRunRecord = {
  schemaVersion: 1;
  runId: string;
  status: ModelRunStatus;
