  name: string;
  sourceIds: readonly string[];
  view: "carousel" | "timeline";
  line: number;
  observations?: readonly CarouselObservation[];
}>;

export type CarouselObservation = Readonly<{
  sourceId: string;
  observedAt?: string;
  location?: string;
  caption?: string;
  notes?: string;
  analysisStatus?: string;
}>;

export type ImageKnowledgeResult = Readonly<{
  sourceId: string;
  sourceRef: string;
  sourceHash: string;
  parser: "image-parser";
  parserVersion: string;
  format: "png" | "jpeg";
  width: number;
  height: number;
  sizeBytes: number;
  extractedText: string;
  description: string | null;
  descriptionMethod: {
    type: "vision";
    adapterId: string;
    adapterVersion: string;
  } | null;
  visualInterpretationAvailable: boolean;
  method: string;
  status: "completed" | "partial";
  warnings: readonly string[];
  errors: readonly string[];
  processedAt: string;
  cacheHit: boolean;
  cacheKey: string;
  configuration: Readonly<{
    ocr: boolean;
    ocrAdapter: string | null;
    visionAdapter: string | null;
  }>;
}>;

export type ImageParseJob = Readonly<{
  id: string;
  entityId: string;
  carouselId: string;
  status: "processing" | "completed" | "partial" | "failed";
  entries: readonly {
    sourceId: string;
    status: "not-parsed" | "processing" | "completed" | "partial" | "failed";
    result: ImageKnowledgeResult | null;
    error: string;
  }[];
}>;

export type IndexValidation = Readonly<{
  menus: readonly IndexedKnowledgeMenu[];
  errors: readonly { line: number; message: string }[];
}>;

export type KnowledgeIndexState = Readonly<{
  priceSymbol?: string;
  sourceNotes?: readonly { sourceId: string; text: string }[];
  draft: string;
  applied: string | null;
  menus: readonly IndexedKnowledgeMenu[];
  revision: string | null;
}>;

export type DailyPriceResponse = Readonly<{
  cached: boolean;
  stale: boolean;
  warning: string | null;
  snapshot: Readonly<{
    symbol: string;
    currency: string;
    exchangeTimezone: string;
    price: number;
    previousClose: number | null;
    marketTime: string;
    marketState: string;
    delayMinutes: number | null;
    fetchedAt: string;
    historyFetchedAt: string;
    history: readonly Readonly<{ date: string; close: number }>[];
    metrics?: Readonly<{
      marketCap: number | null;
      trailingPE: number | null;
      eps: number | null;
      week52Low: number | null;
      week52High: number | null;
      volume: number | null;
    }>;
  }>;
}>;

export type MarketHistoryResponse = Readonly<{
  cached: boolean;
  stale: boolean;
  warning: string | null;
  snapshot: Readonly<{
    provider: "Yahoo Finance";
    symbol: string;
    currency: string | null;
    fetchedAt: string;
    range: "1M" | "3M" | "6M" | "1Y" | "5Y" | "MAX";
    interval: "1d" | "1wk" | "1mo";
    observations: readonly Readonly<{
      date: string;
      open: number | null;
      high: number | null;
      low: number | null;
      close: number | null;
      volume: number | null;
    }>[];
    dividends: readonly Readonly<{ date: string; amount: number | null }>[];
    splits: readonly Readonly<{
      date: string;
      numerator: number | null;
      denominator: number | null;
    }>[];
  }>;
}>;

type PreviewMetadata = Readonly<{
  name: string;
  relativePath: string;
  extension: string;
  size: number;
}>;

export type ExcelSourcePreview = PreviewMetadata &
  Readonly<{
    kind: "excel";
    sourceHash: string;
    engineVersion: string;
    dateSystem: "1900" | "1904";
    cacheHit: boolean;
    sheetIndex: number;
    warnings: readonly string[];
    sheets: readonly Readonly<{
      name: string;
      index: number;
      state: string;
      range: string | null;
      merges: readonly string[];
      warnings: readonly string[];
    }>[];
    page: Readonly<{
      columns: readonly string[];
      rows: readonly Readonly<{
        number: number;
        cells: readonly Readonly<{
          coordinate: string;
          text: string;
          isNumeric: boolean;
        }>[];
      }>[];
      truncated: boolean;
      rowOffset: number;
      columnOffset: number;
      totalRows: number;
      totalColumns: number;
    }>;
    markdown: string;
  }>;

export type WorldViewBridge = {
  request: <T = unknown>(
    operation: WorldViewOperation,
    input: WorldViewRequest,
  ) => Promise<T>;
};
